package main
import("encoding/binary";"encoding/hex";"testing")
func qosFixture()[]byte{b,_:=hex.DecodeString("5201c101090908696e7465726e65740501000000005e04fefe9e9e");return b}
func TestCapturedAMBR100Mbps(t *testing.T){d,e:=parseESMSubscription(qosFixture());if e!=nil||d.QCI!=9||d.Down!=100000||d.Up!=100000||d.APN!="internet"||d.Bearer!=5{t.Fatalf("%+v %v",d,e)}}
func TestAMBRBoundaries(t *testing.T){for _,c:=range []struct{b,x,y byte;n uint64}{{63,0,0,63},{64,0,0,64},{127,0,0,568},{128,0,0,576},{254,0,0,8640},{254,74,0,16000},{254,75,0,17000},{254,158,0,100000},{254,186,0,128000},{254,187,0,130000},{254,250,0,256000},{254,250,1,260000},{254,250,161,1500000},{254,250,162,1600000}}{n,ok:=ambrKbps(c.b,c.x,c.y);if !ok||n!=c.n{t.Fatal(c,n,ok)}};if _,ok:=ambrKbps(0,0,0);ok{t.Fatal("unknown rate treated as a value")}}
func TestDiagFrameValidation(t *testing.T){esm:=qosFixture();frame:=make([]byte,16+len(esm));binary.LittleEndian.PutUint16(frame,uint16(len(frame)));frame[2]=0xe2;frame[3]=0xb0;frame[12]=1;copy(frame[16:],esm);d,e:=parseDiagSubscriptionLine("LOG b0e2 "+hex.EncodeToString(frame));if e!=nil||d.Down!=100000{t.Fatal(d,e)};frame[0]++;if _,e=parseDiagSubscriptionLine("LOG b0e2 "+hex.EncodeToString(frame));e==nil{t.Fatal("bad log length accepted")};if _,e=parseDiagSubscriptionLine("LOG b0e5 "+hex.EncodeToString(frame));e==nil{t.Fatal("state log parsed as AMBR")}}
func TestESMIncompleteAndIMSRejected(t *testing.T){b:=qosFixture();for _,n:=range []int{1,3,6,12,len(b)-1}{if _,e:=parseESMSubscription(b[:n]);e==nil{t.Fatal("truncated message",n)}};b[4]=5;if _,e:=parseESMSubscription(b);e==nil{t.Fatal("IMS QCI accepted")};b=qosFixture();b[2]=0xcd;if _,e:=parseESMSubscription(b);e==nil{t.Fatal("release parsed as rate")}}
